+<?php
+namespace WP_Rocket\Tests\Unit\inc\Engine\Common\JobManager\Cron\Subscriber;
+
+use Mockery;
+use WP_Rocket\Engine\Admin\RocketInsights\Jobs\Factory as RIFactory;
+use WP_Rocket\Engine\Common\JobManager\Cron\Subscriber;
+use WP_Rocket\Engine\Common\JobManager\JobProcessor;
+use WP_Rocket\Engine\Optimization\RUCSS\Jobs\Factory as RUCSSFactory;
+use WP_Rocket\Tests\Fixtures\inc\Engine\Common\JobManager\Manager;
+use WP_Rocket\Tests\Unit\TestCase;
+
+/**
+ * Test class covering \WP_Rocket\Engine\Common\JobManager\Cron\Subscriber::initialize_rucss_queue_runner
+ *
+ * Guards against the regression where Rocket Insights being active kept the RUCSS queue runner
+ * firing even when RUCSS was disabled (issue #8300).
+ *
+ * Positive cases (RUCSS enabled → cron scheduled) require Action Scheduler infrastructure and
+ * are covered by the integration test.
+ */
+class Test_InitializeRucssQueueRunner extends TestCase {
+
+	/**
+	 * Builds a Subscriber with mocked factories where the RUCSS manager returns the given allowed state.
+	 *
+	 * @param bool $rucss_is_allowed Whether the RUCSS manager should report allowed.
+	 * @return array{ 0: Subscriber }
+	 */
+	private function makeSubscriber( bool $rucss_is_allowed ): array {
+		$rucss_manager = Mockery::mock( Manager::class );
+		$rucss_manager->expects()->is_allowed()->once()->andReturn( $rucss_is_allowed );
+
+		$rucss_factory = Mockery::mock( RUCSSFactory::class );
+		$rucss_factory->expects()->manager()->once()->andReturn( $rucss_manager );
+
+		$ri_factory = Mockery::mock( RIFactory::class );
+		$ri_factory->expects()->manager()->never();
+
+		$subscriber = new Subscriber(
+			Mockery::mock( JobProcessor::class ),
+			[
+				'rucss'           => $rucss_factory,
+				'rocket_insights' => $ri_factory,
+			]
+		);
+
+		return [ $subscriber, $rucss_factory, $ri_factory ];
+	}
+
+	/**
+	 * Queue runner must not initialize when both RUCSS and Rocket Insights are disabled.
+	 *
+	 * @return void
+	 */
+	public function testShouldNotInitWhenRUCSSDisabledAndRIDisabled(): void {
+		[ $subscriber ] = $this->makeSubscriber( false );
+		$subscriber->initialize_rucss_queue_runner();
+	}
+
+	/**
+	 * Queue runner must not initialize when RUCSS is disabled even if Rocket Insights is active.
+	 * Regression: JobProcessor::is_allowed() returned true when only RI was active (issue #8300).
+	 *
+	 * @return void
+	 */
+	public function testShouldNotInitWhenRUCSSDisabledAndRIEnabled(): void {
+		[ $subscriber ] = $this->makeSubscriber( false );
+		$subscriber->initialize_rucss_queue_runner();
+	}
+}

